new_method='''    private func setupBackgroundObservers() {\n        let nc = NotificationCenter.default\n        backgroundObservers.append(nc.addObserver(forName: UIApplication.didEnterBackgroundNotification, object: nil, queue: .main) { [weak self] _ in\n            Task { @MainActor [weak self] in\n                guard let self else { return }\n                self.isAppInBackground = true\n                self.enteredBackgroundAt = Date()\n                // Không phát audio giả và không gửi heartbeat/movement khi app xuống nền.\n                // iOS có thể tạm dừng TCP; để socket chết tự nhiên thay vì tạo lỗi POSIX 89\n                // ngay lập tức và hiện banner giống một packet send lỗi.\n                self.stopWatchdog()\n                self.stopIdleAliveTicker()\n                BackgroundKeepAlive.shared.stop()\n            }\n        })\n        backgroundObservers.append(nc.addObserver(forName: UIApplication.willEnterForegroundNotification, object: nil, queue: .main) { [weak self] _ in\n            Task { @MainActor [weak self] in\n                guard let self else { return }\n                self.isAppInBackground = false\n                let backgroundDuration = self.enteredBackgroundAt.map { Date().timeIntervalSince($0) } ?? 0\n                self.enteredBackgroundAt = nil\n                BackgroundKeepAlive.shared.stop()\n\n                guard self.shouldStayConnected else { return }\n                // Chỉ xác định socket đã chết sau khi quay lại foreground.\n                // Không coi việc vừa rời app là disconnect tức thời.\n                let silentFor = Date().timeIntervalSince(self.lastPacketReceivedAt)\n                if self.pendingBackgroundNetworkFailure != nil || self.connection == nil ||\n                    (self.state == .connected && (backgroundDuration >= 10 && silentFor >= 10)) {\n                    let reason = self.pendingBackgroundNetworkFailure ?? "socket không còn khả dụng sau khi app chạy nền"\n                    self.pendingBackgroundNetworkFailure = nil\n                    self.appendLog(.error, "Lỗi kết nối: The operation couldn’t be completed. (Network.NWError error 89 - Operation canceled by system/peer). \\(reason)")\n                    self.scheduleReconnect(reason: "socket stale sau khi quay lại app")\n                } else if self.state == .connected {\n                    self.startWatchdog()\n                    self.startIdleAliveTicker()\n                } else if self.state != .connecting && self.state != .loggingIn {\n                    self.scheduleReconnect(reason: "quay lại ứng dụng")\n                }\n            }\n        })\n    }\n\n'''
