newret='''    // NBT string dạng 1.12: Enchantments:[{id:"minecraft:sharpness",lvl:5s}, ...]\n    if let enchRegex = try? NSRegularExpression(pattern: #"Enchantments\\s*[:=]\\s*\\[([^\\]]*)\\]"#),\n       let em = enchRegex.firstMatch(in: raw, range: NSRange(raw.startIndex..., in: raw)),\n       let er = Range(em.range(at: 1), in: raw) {\n        let body = String(raw[er])\n        if let one = try? NSRegularExpression(pattern: #"id\\s*[:=]\\s*[\\\"']?([A-Za-z0-9_:\\-.]+)[\\\"']?[^{}]*?lvl\\s*[:=]\\s*(-?\\d+)"#) {\n            for m in one.matches(in: body, range: NSRange(body.startIndex..., in: body)) {\n                guard let ir = Range(m.range(at: 1), in: body), let lr = Range(m.range(at: 2), in: body) else { continue }\n                let id = String(body[ir]).replacingOccurrences(of: "minecraft:", with: "")\n                let lvl = Int(body[lr]) ?? 1\n                enchantments.append("\\(friendlyEnchantmentName(id)) \\(romanNumeral(lvl))")\n            }\n        }\n    }\n    return MCChatHoverItem(resourceName: "minecraft:\\(resourceName)", displayName: displayName,\n                           count: count, legacyItemId: legacyItemID(for: resourceName), damage: damage,\n                           lore: lore, enchantments: enchantments, rawValue: raw)'''
