# Add helper functions before friendlyItemName.
needle='''private func friendlyItemName(_ resourceName: String) -> String {'''
helpers='''private func parseEnchantments(_ value: Any?) -> [String] {\n    guard let arr = value as? [Any] else { return [] }\n    var result: [String] = []\n    for element in arr {\n        if let dict = element as? [String: Any] {\n            let rawID = (dict["id"] as? String) ?? (dict["Id"] as? String) ?? ""\n            let rawLevel: Int = {\n                if let n = dict["lvl"] as? NSNumber { return n.intValue }\n                if let n = dict["level"] as? NSNumber { return n.intValue }\n                if let s = dict["lvl"] as? String { return Int(s) ?? 1 }\n                return 1\n            }()\n            let id = rawID.replacingOccurrences(of: "minecraft:", with: "")\n            guard !id.isEmpty else { continue }\n            result.append("\\(friendlyEnchantmentName(id)) \\(romanNumeral(rawLevel))")\n        }\n    }\n    return result\n}\n\nprivate func friendlyEnchantmentName(_ id: String) -> String {\n    let key = id.replacingOccurrences(of: "_", with: " ")\n    return key.split(separator: " ").map { $0.prefix(1).uppercased() + $0.dropFirst() }.joined(separator: " ")\n}\n\nprivate func romanNumeral(_ number: Int) -> String {\n    if number <= 0 { return "I" }\n    let values: [(Int, String)] = [(1000,"M"),(900,"CM"),(500,"D"),(400,"CD"),(100,"C"),(90,"XC"),(50,"L"),(40,"XL"),(10,"X"),(9,"IX"),(5,"V"),(4,"IV"),(1,"I")]\n    var n = number\n    var out = ""\n    for (v, s) in values {\n        while n >= v { out += s; n -= v }\n    }\n    return out\n}\n\n'''
s=s.replace(needle,helpers+needle)
mcclient.write_text(s)

